// Datas comemorativas (fixas e móveis). Aniversário de Ivatuba e eventos
// municipais são cadastrados pelo agente em "Datas locais" (não inventamos a data).
export function datasComemorativas(ano) {
  const nDom = (mes, n) => { const d = new Date(ano, mes - 1, 1); const off = (7 - d.getDay()) % 7; return new Date(ano, mes - 1, 1 + off + 7 * (n - 1)); };
  const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const f = (m, d) => `${ano}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  return [
    { data: f(3, 8), titulo: "Dia Internacional da Mulher", seg: ["saloes", "costureiras", "estetica"], ideia: "Campanha Micro Mulher: visitar empreendedoras e divulgar o Banco da Mulher Paranaense." },
    { data: f(3, 15), titulo: "Dia do Consumidor", seg: ["roupas", "presentes", "variedades"], ideia: "Lojistas preparam promoções: oportunidade de estoque e capital de giro." },
    { data: f(5, 1), titulo: "Dia do Trabalhador", seg: ["autonomos", "eletricistas", "limpeza"], ideia: "Autônomos: formalização como MEI e crédito para ferramentas." },
    { data: iso(nDom(5, 2)), titulo: "Dia das Mães", seg: ["presentes", "saloes", "roupas"], ideia: "Ação 45 dias antes: estoque para a 2ª maior data do comércio." },
    { data: f(6, 12), titulo: "Dia dos Namorados", seg: ["presentes", "restaurantes", "fotografos"], ideia: "Restaurantes, presentes e serviços: estrutura e estoque para a data." },
    { data: f(7, 16), titulo: "Dia do Comerciante", seg: ["mercados", "construcao", "moveis"], ideia: "Homenagear comerciantes e apresentar as linhas de capital de giro." },
    { data: iso(nDom(8, 2)), titulo: "Dia dos Pais", seg: ["calcados", "barbearias", "presentes"], ideia: "Estoque e serviços masculinos para a data." },
    { data: f(9, 15), titulo: "Dia do Cliente", seg: ["roupas", "farmacias", "saloes"], ideia: "Pós-atendimento: ligar para clientes que já tomaram crédito e pedir indicações." },
    { data: f(10, 5), titulo: "Dia Nacional da Micro e Pequena Empresa", seg: ["mercearias", "papelarias", "autonomos"], ideia: "Mutirão de atendimento na Sala do Empreendedor." },
    { data: f(10, 12), titulo: "Dia das Crianças", seg: ["variedades", "presentes", "calcados"], ideia: "Lojas de brinquedos e variedades: estoque da data." },
    { data: iso(new Date(nDom(11, 4).getTime() + 5 * 864e5)), titulo: "Black Friday", seg: ["moveis", "roupas", "calcados"], ideia: "Comércio compra estoque com desconto: capital de giro." },
    { data: f(12, 25), titulo: "Natal", seg: ["presentes", "roupas", "variedades"], ideia: "Maior data do comércio: estoque e reforma de loja (abordar em outubro)." },
  ];
}

