const TOM = {
  comercio: { cump: "Bom dia", ref: "sua loja", gancho: "as vendas das próximas datas" },
  servicos: { cump: "Olá", ref: "seu trabalho", gancho: "atender mais clientes" },
  industria: { cump: "Bom dia", ref: "sua produção", gancho: "produzir mais" },
  agro: { cump: "Bom dia", ref: "sua propriedade", gancho: "produzir e vender melhor" },
  outro: { cump: "Olá", ref: "seu negócio", gancho: "crescer" },
};

export function montarMensagem(tipo, d = {}) {
  const t = TOM[d.categoria] || TOM.outro;
  const nome = (d.nome || "").split(" ")[0] || "tudo bem";
  const ag = d.agente || "o Agente de Crédito";
  const ativ = d.atividade ? d.atividade.toLowerCase() : "empreendedores";
  const linha = d.linha || "as linhas da Fomento Paraná";
  const inv = d.investimento ? d.investimento.toLowerCase() : "um investimento no negócio";
  const M = {
    primeiro: `${t.cump}, ${nome}! Aqui é ${ag}, Agente de Crédito da Fomento Paraná em Ivatuba. Estou conversando com ${ativ} da cidade sobre crédito para ${t.gancho}. Posso te visitar ou te ligar em 10 minutos esta semana?`,
    presencial: `${t.cump}! Sou ${ag}, Agente de Crédito da Fomento Paraná, atendo aqui em Ivatuba. Não vim vender nada: vim entender o que ${t.ref} precisa para ${t.gancho}. Se tivesse um valor hoje para investir, onde colocaria primeiro?`,
    ligacao: `Roteiro: 1) "${t.cump}, ${nome}, aqui é ${ag}, Agente de Crédito da Fomento Paraná. Tem dois minutinhos?" 2) Diga o motivo: estou ajudando ${ativ} a conseguir crédito para ${inv}. 3) Pergunte: "Isso faz sentido para você hoje?" 4) Se sim, agende uma visita. Se não, pergunte quando seria um bom momento.`,
    whatsapp: `${t.cump}, ${nome}! 👋 Sou ${ag}, Agente de Crédito da Fomento Paraná em Ivatuba. A Fomento tem crédito para ${ativ} investirem em ${inv}. Quer que eu te explique como funciona? É só responder aqui. 😉`,
    linha: `${nome}, sobre ${linha}: é uma linha da Fomento Paraná, agência de crédito do Governo do Paraná. Te mando aqui as condições oficiais atualizadas e vemos juntos se encaixa no que você precisa (${inv}). A aprovação depende da análise de crédito.`,
    recuperar: `Oi, ${nome}! Tudo bem? Conversamos um tempo atrás sobre crédito para ${inv}. Ainda está nos seus planos? Se quiser, retomamos de onde paramos, sem compromisso.`,
    documentacao: `Oi, ${nome}! Para seguir com sua proposta só falta${d.pendencias ? `: ${d.pendencias}` : " a documentação que combinamos"}. Se precisar de ajuda para conseguir algum documento, me chama que eu te oriento.`,
    orcamento: `Oi, ${nome}! Conseguiu o orçamento de ${inv}? Com ele em mãos já consigo montar a proposta. Pode mandar foto aqui mesmo.`,
    proposta: `Oi, ${nome}! Passando para te atualizar: sua proposta está ${d.situacao || "em andamento"}. Assim que tiver novidade te aviso. Qualquer dúvida, estou à disposição.`,
    pos: `Oi, ${nome}! Como está ${t.ref} depois do investimento? Deu tudo certo com ${inv}? Se precisar de alguma orientação, conte comigo.`,
    agradecimento: `${nome}, muito obrigado pela confiança! Foi um prazer te atender. Desejo muito sucesso para ${t.ref}. 🙌`,
    indicacao: `${nome}, que bom que deu certo! Você conhece outro empreendedor que também poderia ser ajudado pela Fomento Paraná? Se puder me passar o contato (com a permissão dele), eu faço o atendimento com o mesmo cuidado.`,
  };
  return M[tipo] || M.primeiro;
}

